from pathlib import Path
import html,json,re,shutil
R=Path(__file__).resolve().parents[5];D=Path(__file__).resolve().parent;C=Path('/tmp/medina-source-cache/endocrinologie/E35')
assert not (D/'source-binding.json').exists(),'Final evidence sealed; never refresh automatically.'
assert 'VÉRITÉ OK' in (D/'research-gate.log').read_text()
ledger=json.loads((D/'source-ledger.json').read_text())['sources'];pops=[];summaries=[]
def w(k,label):return f'<button class="w" data-k="e35-{k}">{label}</button>'
def table(h,rows):return '<table class="t" data-e35-table="1"><thead><tr>'+''.join('<th>'+x+'</th>' for x in h)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
def pop(k,title,body):pops.append(f'<template data-pop="e35-{k}" data-title="{html.escape(title,quote=True)}">{body}</template>')
def sec(k,title,body,summary):
 a='e35-'+str(k);pk='pareto-'+a;summaries.append(f'<template data-pop="{pk}" data-title="Essentiel — {html.escape(title,quote=True)}"><p>{summary}</p><p class="ratio" data-cover="{a}"></p></template>')
 return f'<section class="ilot" id="{a}"><h2><span class="n">{k}</span>{title}</h2>{body}<div class="key"><b>À retenir.</b> {summary}</div><button class="pareto-btn ui" data-k="{pk}">Essentiel de cette partie</button></section>'
def logical(a,b,c,caption):
 t='<figure><svg role="img" viewBox="0 0 450 246" aria-label="Schéma logique sans anatomie générée">'
 for i,label in enumerate([a,b,c]):
  y=5+80*i;t+=f'<rect x="8" y="{y}" width="434" height="54" rx="8" fill="none" stroke="currentColor"/><text x="225" y="{y+33}" font-size="17" fill="currentColor" text-anchor="middle">{label}</text>'
  if i<2:t+=f'<path d="M225 {y+54}v26m-5-7 5 7 5-7" stroke="currentColor" fill="none"/>'
 return t+'</svg><figcaption>Schéma logique original Sol2026, sans anatomie générée. '+caption+'</figcaption></figure>'
S=[]
S.append(sec(1,'Deux mécanismes à traiter ensemble','''<p>Un homme fictif de vingt ans présente fièvre, vomissements, purpura et choc. Une femme fictive de quarante-deux ans, traitée pour une tuberculose surrénalienne, devient très faible et hypotendue après une gastroentérite. Les causes immédiates diffèrent, mais le raisonnement est commun : reconnaître la défaillance, traiter l’infection ou le déclencheur, et ne pas retarder une substitution parentérale si une crise surrénalienne est suspectée [S4–S8].</p><p>Dans le premier cas, l’hémorragie surrénalienne septique peut accompagner une infection fulminante. Dans le second, la glande déjà lésée peut ne plus répondre au stress, et les vomissements compromettent la prise orale. L’antibiothérapie, le soutien circulatoire et le remplacement hormonal nécessaire s’organisent en parallèle ; attendre le résultat d’un test hormonal ou d’une imagerie ne doit pas retarder les premières mesures [S4–S6, S8, S10].</p><p>La formation suisse PROFILES demande de reconnaître choc, hypotension sévère, méningisme, altération de conscience et douleur abdominale, puis d’initier les soins et de transmettre les informations utiles. Ce rapprochement avec E35 est pédagogique, sans correspondance officielle entre code et question fédérale. Les vignettes sont originales [S24].</p>''','L’infection et la défaillance endocrine peuvent coexister. Traiter l’une n’autorise pas à attendre pour l’autre [S4–S8].'))
S.append(sec(2,'Définition et double codage','''<p>E35 désigne des anomalies endocriniennes au cours de maladies classées ailleurs. Les subdivisions portent un astérisque : elles décrivent une manifestation d’organe et ne s’utilisent pas seules. Le code étiologique primaire classe la maladie causale ; le code de manifestation ajoute la conséquence endocrine lorsqu’il est approprié [S1–S3].</p>'''+table(['Manifestation locale suisse2024','Exemple expressément nommé dans les notes allemandes','Portée'],[['E35.0* : thyroïde','Tuberculose thyroïdienne, A18.8†','Cause et atteinte glandulaire sont documentées ensemble.'],['E35.1* : surrénale','Addison tuberculeux, A18.7† ; Waterhouse-Friderichsen méningococcique, A39.1†','Un syndrome septique dû à un autre germe ne reçoit pas automatiquement A39.1†.'],['E35.8* : autres glandes','Aucune entité particulière nommée dans cette rubrique2024','Absence d’exemple n’est pas preuve de rubrique vide ; vérifier diagnostic et index de codage.']])+'''<p>Les inclusions infectieuses nommées servent de modèles cliniques à la leçon ; elles ne démontrent pas que toute E35 serait exclusivement infectieuse. À l’inverse, toute insuffisance surrénalienne, thyroïdite ou maladie intercurrente ne reçoit pas E35. Une insuffisance auto-immune, génétique ou médicamenteuse garde son diagnostic et sa classification propres [S1–S4].</p><p>La classification suisse locale est celle de2024, confrontée aux notes allemandes et au principe dague-astérisque. Ces références ne sont ni un certificat de codage individuel2026 ni une règle de remboursement. Le diagnostic médical précède le choix des codes [S1–S3].</p>''','L’astérisque documente une manifestation ; il ne remplace jamais la cause. Le libellé ne prescrit pas le traitement [S1–S3].'))
S.append(sec(3,'Épidémiologie : ne pas mesurer la mauvaise maladie','''<p>Aucune incidence suisse de l’ensemble des manifestations E35, de la tuberculose surrénalienne ou de la tuberculose thyroïdienne n’est établie dans les lectures ciblées. Les données disponibles concernent surtout la maladie causale, des populations spécialisées ou des cas publiés [S8–S12, S14, S15].</p><p>Le guide suisse de la tuberculose V1.2024 rapporte365cas en2022, soit4,16pour100000habitants. Il indique une atteinte pulmonaire dans94%des cas de2020 ; cela ne signifie pas que6%seulement auraient une atteinte extrapulmonaire, car les localisations peuvent coexister. Ces chiffres ne donnent pas la part endocrine ni une incidence2026 [S9].</p><p>Le document OFSP du20janvier2025 décrit environ48infections invasives à méningocoque par an en moyenne décennale, incidence0,6pour100000, et une létalité de5–15%. Ces données concernent toutes les infections invasives de cette population, pas spécifiquement le syndrome de Waterhouse-Friderichsen. Une synthèse médico-légale de86décès sélectionnés ne peut pas fournir une létalité de tous les patients atteints [S8, S15].</p><p>En Suède,29des1743patients avec traumatisme abdominal grave avaient une lésion surrénalienne dans une série2013–2018. Cette fréquence de1,7%ne décrit pas les infections surrénaliennes. Une revue de tuberculose thyroïdienne avec abcès réunissait33cas publiés dans22études ; elle ne permet pas de calculer un risque populationnel. La sélection et les examens incomplets limitent toute extrapolation [S11, S12].</p>''','L’incidence de l’infection causale n’est pas celle de sa complication endocrine. Chaque chiffre garde sa période et son dénominateur [S8–S12].'))
S.append(sec(4,'Du fonctionnement normal à la défaillance','''<p>Le cortex surrénalien produit des stéroïdes ; la médulla produit des catécholamines. Le cortisol participe à la réponse métabolique et circulatoire au stress. L’aldostérone contribue à la conservation du sodium et à l’excrétion du potassium ; sa régulation dépend surtout du système rénine-angiotensine et du potassium, et ne se réduit pas à l’axe corticotrope [S4, S23].</p><p>Une destruction corticale bilatérale peut diminuer cortisol et aldostérone. L’atteinte centrale ou la suppression par des glucocorticoïdes réduit surtout le signal corticotrope et conserve généralement la régulation minéralocorticoïde. Cela explique pourquoi une même hyponatrémie ne prouve pas un même mécanisme et pourquoi la fludrocortisone n’est pas ajoutée à tous les déficits [S4–S6].</p><p>Infection granulomateuse, nécrose, infarctus ou hémorragie peuvent détruire du tissu. Une glande touchée à l’imagerie ne signifie pas automatiquement perte complète de réserve ; l’étendue et l’évolution comptent. Une hémorragie unilatérale ne produit habituellement pas le même risque qu’une atteinte bilatérale, sans exclure une lésion controlatérale moins visible [S10, S11, S14].</p><p>La thyroïde normale est organisée en follicules autour d’un colloïde. Une infection peut produire masse, collection ou granulomes tout en conservant une sécrétion hormonale suffisante. Fonction normale et absence d’infection ne sont donc pas synonymes [S12, S13, S25].</p>'''+logical('Maladie causale et tissu atteint','Réserve hormonale et réponse au stress','Signes, examens puis soins parallèles','La lésion et la fonction s’évaluent ensemble ; aucune perte de réserve chiffrée universelle n’est déduite du dessin [S4, S10, S12].'),'L’organe, le niveau de l’atteinte et la réserve expliquent le tableau. Cortex, médulla et thyroïde ne sont pas interchangeables [S4, S23, S25].'))
S.append(sec(5,'Mécanismes, causes et diagnostics voisins',table(['Profil','Causes ou contexte','Question utile'],[['Atteinte surrénalienne infectieuse chronique','Tuberculose ; autres agents selon terrain et exposition, notamment certaines mycoses.','Réserve hormonale, microbiologie, autres localisations et résistances.'],['Atteinte hémorragique aiguë','Sepsis, trouble de coagulation/anticoagulants, traumatisme, contexte tumoral ou obstétrical.','Stabilité, caractère bilatéral, saignement persistant, cause sous-jacente.'],['Tuberculose thyroïdienne','Masse ou collection, parfois avec adénopathie, fonction souvent conservée.','Prélèvement pertinent et confirmation microbiologique, pas image spécifique.'],['Déficit sans infection glandulaire','Auto-immunité, anomalie congénitale, atteinte centrale, exposition aux glucocorticoïdes.','Ne pas attribuer automatiquement E35 ni perdre la cause réelle.']])+'''<p>Le syndrome de Waterhouse-Friderichsen associe un tableau septique fulminant et une hémorragie surrénalienne bilatérale. Le méningocoque est classique, mais d’autres agents sont décrits. Une série d’autopsies de décès ne remplace pas un test clinique prospectif, et le code méningococcique reste lié à cette étiologie [S2, S8, S15].</p><p>Le terrain oriente la recherche : traitement immunosuppresseur, exposition tuberculeuse, maladie ou voyage, hémopathie, anticoagulation et antécédent de crise. Une insuffisance congénitale peut être révélée par une infection sans que l’infection ait détruit la glande ; ce sont deux mécanismes différents [S4, S6, S10, S14].</p>''','Distinguer cause glandulaire, déclencheur d’une crise et diagnostic voisin. Le déclencheur n’est pas toujours l’étiologie du déficit [S4, S6, S10].'))
S.append(sec(6,'Anamnèse : chronologie, traitements et absorption','''<p>Préciser fatigue, amaigrissement, appétit, envies de sel, vertiges au lever, douleurs abdominales, vomissements et évolution. Dater fièvre, céphalée, purpura, exposition et symptômes cervicaux. La progression lente d’une insuffisance n’a pas le même calendrier qu’une hémorragie septique ou qu’une malabsorption aiguë d’un traitement habituel [S4–S6, S8, S10, S12].</p><p>Demander une insuffisance connue, une carte et un kit d’urgence, la dernière prise réellement absorbée et les adaptations prévues en cas de maladie. Rechercher toutes les voies de glucocorticoïdes, une diminution ou un arrêt récent, ainsi que les traitements oncologiques ou autres causes susceptibles d’altérer les axes endocriniens. La voie non orale n’exclut pas une suppression de l’axe [S4, S6, S7].</p><p>La rifampicine peut accélérer le métabolisme de l’hydrocortisone. Vérifier son début ou son arrêt, l’observance, les médicaments associés et les symptômes de sous- ou sur-remplacement. Une augmentation chiffrée identique chez tous n’est pas déduite du seul nom de l’antibiotique [S6, S16, S20].</p><p>Pour une tuberculose suspectée, rechercher contacts, localisations antérieures, traitements et résistances connus, sans inférer une cause sur le pays de naissance seul. Une absence d’exposition identifiée, de signes généraux ou de lésion pulmonaire n’exclut pas une atteinte thyroïdienne. Un nodule suspect garde aussi ses diagnostics tumoraux [S9, S12, S13].</p>''','Le traitement reçu, celui réellement absorbé et son calendrier font partie du diagnostic. Une infection peut révéler un déficit préexistant [S4, S6, S16].'))
S.append(sec(7,'Examen clinique et sémiologie','''<div data-semiology-clinical="E35"><p>Commencer par vigilance, respiration, perfusion, pression artérielle, fréquence cardiaque, température et signes de déshydratation. Un choc ou une détérioration rapide commande le niveau de soins. Rechercher purpura et signes méningés selon contexte, mais leur absence ne rassure pas à elle seule, notamment chez le petit enfant [S4, S5, S8, S22, S24].</p><p>Dans une forme chronique, décrire amaigrissement, hypotension orthostatique et hyperpigmentation des plis, cicatrices ou muqueuses. La pigmentation traduit une stimulation corticotrope prolongée ; elle peut manquer dans une atteinte primaire très aiguë et n’est pas attendue de la même façon dans un déficit central. Un potassium normal n’exclut pas une crise [S4, S5, S10].</p><p>Examiner abdomen et flancs si douleur, et rechercher une masse cervicale, sa sensibilité, les adénopathies, la voix, la déglutition et la respiration. L’examen ne distingue pas à lui seul tuberculose, collection pyogène, inflammation et tumeur thyroïdienne. Une fonction hormonale encore normale ne remplace pas la caractérisation d’une masse [S10, S12, S13].</p><p>La sémiologie clinique est reliée aux neuf volets du premier sous-onglet scientifique : normal, signes, mécanismes, examen, interprétation, différentiels, urgence, limites et sources. Aucun score E35 clinique unique n’est proposé [S4–S6, S24].</p></div>''','La gravité précède l’étiquette. Ni absence de pigmentation ni ionogramme normal ne permettent d’attendre devant une crise plausible [S4, S5, S10].'))
S.append(sec(8,'Urgence : agir sans attendre la preuve','''<p>Hypotension ou choc, altération de conscience, hypoglycémie, vomissements persistants, purpura ou détresse respiratoire justifient une évaluation et des soins urgents. Les mécanismes septique, hypovolémique et endocrinien peuvent coexister. Si une crise surrénalienne est suspectée, l’hydrocortisone parentérale et la réanimation liquidienne adaptée ne doivent pas attendre un test dynamique [S4–S8].</p><p>Si cela ne retarde pas le traitement, prélever cortisol et hormone adrénocorticotrope, glycémie, ionogramme et examens infectieux pertinents avant la première dose. Sinon, traiter et compléter ensuite la démarche. Surveiller de façon répétée circulation, conscience, glucose et électrolytes ; l’imagerie ne doit pas devenir un obstacle aux premières mesures [S4–S7, S10].</p><p>Chez l’adulte, les guides décrivent100mg d’hydrocortisone intraveineuse ou intramusculaire puis200mg sur24heures, ou50mg toutes les six heures selon le protocole. La FI suisse précise formulation, voie et technique ; l’injection intraveineuse de100mg se fait en au moins30secondes. Les schémas pédiatriques sont distincts et ne reçoivent pas un bolus adulte uniforme [S5–S7, S16].</p><p>Une infection invasive à méningocoque suspectée impose hospitalisation, antibiotique urgent, précautions et déclaration sans attendre la confirmation. Les petites doses utilisées chez un contact sain ne sont pas celles d’un malade avec sepsis ou méningite. Identifier les contacts vient en parallèle des soins du patient, avec le service cantonal [S8, S19, S22].</p>''','Prélèvements si possibles, traitement sans délai indu. Le protocole adulte n’est pas une prescription universelle pédiatrique [S4–S8, S16].'))
S.append(sec(9,'Diagnostic : confirmer la fonction et la cause','''<p>La crise reste un diagnostic clinique urgent. Hors phase critique et hors interférence majeure, le cortisol matinal aide à évaluer la réserve. Le guide britannique donne, chez les personnes d’au moins un an et avec immunodosages modernes, moins de150nmol/L comme suspect,150–300comme incertain et plus de300comme rendant un déficit très improbable. Ces repères ne sont pas une règle de non-traitement en choc, et d’autres méthodes ont d’autres références [S4, S5].</p><p>Associer le signal corticotrope au cortisol pour distinguer atteinte primaire et centrale, puis rénine, aldostérone et ionogramme selon le profil. Les conditions de prélèvement, glucocorticoïdes reçus, œstrogènes et protéines de transport modifient l’interprétation. Un test de stimulation se discute à l’état stable si le bilan reste incertain ; sa réponse garde le seuil propre à la méthode [S4, S5, S10].</p><p>L’imagerie surrénalienne recherche hémorragie, infarctus, infiltration et masses ; elle ne confirme pas seule une infection spécifique. Une lésion bilatérale augmente la vigilance pour la réserve, sans transformer toute image en crise. La recherche d’une tumeur ou d’un trouble de coagulation dépend du contexte, après stabilisation si nécessaire [S10, S11, S14].</p><p>Pour une masse thyroïdienne ou une collection, échographie et prélèvement orienté peuvent apporter cytologie, histologie, culture et amplification ciblée. Des granulomes ou des bacilles acido-alcoolo-résistants ne prouvent pas à eux seuls l’espèce du complexe tuberculeux ; documenter le germe et les résistances évite un traitement mal ciblé. Un test immunologique positif ne localise pas une atteinte endocrine [S9, S12, S13].</p>''','La fonction endocrine et l’étiologie sont deux preuves complémentaires. Image, histologie et microbiologie ne se remplacent pas [S4, S9, S10, S12].'))
S.append(sec(10,'Prise en charge selon la situation','''<p>La crise suspectée reçoit traitement hormonal parentéral, correction hydroélectrolytique et prise en charge du déclencheur. La voie orale revient quand l’état est stable et l’absorption fiable. Diminuer ensuite selon l’évolution et le plan spécialisé ; ne pas interrompre le remplacement indispensable sous prétexte que l’infection a été traitée [S4–S7, S16, S17].</p><p>La tuberculose glandulaire nécessite une stratégie antituberculeuse combinée, fondée sur prélèvements, sensibilité, sites, terrain et recommandations suisses datées. Le guide V1.2024 décrit un schéma standard de six mois pour les situations usuelles, avec exceptions. Un schéma court étudié pour la tuberculose pulmonaire ne se transfère pas automatiquement à la thyroïde ou à la surrénale ; la rifampicine n’est pas utilisée seule pour traiter la tuberculose [S9, S12, S20].</p><p>Une collection thyroïdienne peut demander aspiration ou drainage, et une compression des voies aériennes ou une suspicion tumorale persistante peut modifier l’indication chirurgicale. Les résections historiques fréquentes reflètent parfois une incertitude diagnostique avant reconnaissance de la tuberculose, pas une nécessité de retirer toute thyroïde infectée [S12, S13].</p><p>L’hémorragie surrénalienne se traite selon stabilité, caractère persistant du saignement et cause sous-jacente. Une surveillance conservatrice est fréquente ; embolisation ou chirurgie sont discutées si indiquées. Une revue proposant une stratégie très chirurgicale ne justifie pas l’opération de toute hémorragie, en particulier dans un contexte septique déjà instable [S10, S11].</p><p>En insuffisance primaire avec déficit minéralocorticoïde, un remplacement spécifique peut devenir nécessaire. Les doses de stress d’hydrocortisone ont déjà une activité minéralocorticoïde ; on ne triple donc pas automatiquement Florinef. Dans une insuffisance centrale sans déficit aldostéronique, ce médicament n’est pas ajouté par principe [S4, S6, S7, S10, S18].</p>''','Traiter la cause et remplacer ce qui manque, avec un niveau de soins adapté. Une guérison microbiologique ne garantit pas la récupération glandulaire [S9, S10, S14].'))
S.append(sec(11,'Contacts, prophylaxie et santé publique suisse','''<p>Selon l’OFSP2025, les contacts étroits d’un cas possible, probable ou confirmé d’infection invasive à méningocoque sont évalués rapidement. La période pertinente va de sept jours avant les signes à24heures après le début d’un traitement spécifique. Vie dans le même foyer ou situation comparable, contact intense avec sécrétions et certaines situations de petite enfance répondent aux critères ; la proximité spatiale seule ou la même classe scolaire ne suffit pas toujours [S8].</p><p>La chimioprophylaxie est débutée idéalement dans les24heures et n’est indiquée que si elle peut commencer dans les dix jours suivant l’exposition selon ce document. Elle ne remplace pas l’information sur les signes d’alerte ni l’évaluation d’une personne déjà symptomatique. Le choix dépend de l’âge, de la grossesse, des contre-indications et des interactions [S8, S19–S21].</p><p>Le protocole suisse prévoit ciprofloxacine en premier choix hors grossesse, et rifampicine ou ceftriaxone comme alternatives selon les groupes. Certaines conduites pédiatriques ou d’allaitement diffèrent de la FI du produit : elles sont identifiées dans Pharmacologie, pas présentées comme une autorisation uniforme de la FI. La vaccination post-exposition est discutée selon sérogroupe, âge, antécédents et contexte, avec les autorités [S8, S19–S21].</p><p>La suspicion de méningococcie invasive est à déclarer dans24heures selon l’OFSP2025. Le guide suisse de tuberculose V1.2024 distingue déclaration clinique sous une semaine et déclaration de laboratoire dans24heures. Les formulaires et règles courantes sont vérifiés par l’équipe ; le code E35 seul ne remplace pas la déclaration de la maladie causale [S8, S9].</p>''','Prophylaxie d’un contact sain et traitement d’un cas malade ont des objectifs et des doses différents [S8, S19–S22].'))
S.append(sec(12,'Suivi, pronostic et prévention des crises','''<p>Après une lésion surrénalienne bilatérale, le déficit peut persister malgré la résolution de l’infection ou de l’hémorragie. Une récupération est parfois possible, mais l’arrêt du remplacement exige une évaluation spécialisée de la réserve. Le suivi de l’image recherche aussi une éventuelle lésion sous-jacente, sans calendrier universel appliqué à toutes les causes [S10, S14].</p><p>Évaluer symptômes de sous- et sur-remplacement, pression couchée/debout, poids, électrolytes et, pour le minéralocorticoïde, rénine selon indication. Chez l’enfant, suivre croissance et développement. Une dose chronique excessive n’est pas une solution à toute fatigue ; une maladie intercurrente et une mauvaise absorption demandent un autre raisonnement [S4, S5, S17, S18].</p><p>La personne et son entourage reçoivent un plan écrit de stress, une carte et un kit adaptés, avec entraînement réel à l’injection et règles en cas de vomissements. Renouveler les explications et préparer voyages, procédures et transitions de soins évite que les connaissances restent théoriques. Un contrôle biologique programmé ne remplace pas l’action devant une dégradation aiguë [S4–S7].</p><p>Après tuberculose thyroïdienne, suivre réponse clinique, résolution de la collection et fonction selon le cas. Les séries publiées ont des suivis incomplets : une absence de complication rapportée n’est pas un risque nul. Le suivi infectieux et celui de la fonction hormonale sont coordonnés [S9, S12].</p>''','Suivre l’infection, la lésion et la réserve hormonale séparément. Le plan d’urgence doit pouvoir être appliqué au moment utile [S4, S5, S9, S10].'))
S.append(sec(13,'Populations particulières et choix du produit','''<p>Le nouveau-né et le jeune enfant n’ont pas une version réduite arbitraire du bolus adulte. Le protocole pédiatrique distingue âge, poids et âge gestationnel corrigé ; les options ne s’additionnent pas. Les tableaux de différentes sources ont des bornes différentes et ne sont pas fusionnés en une nouvelle règle [S4, S7, S16].</p><p>Grossesse et allaitement imposent un choix individualisé, tout en maintenant le remplacement vital nécessaire. Les FI de l’hydrocortisone et de la fludrocortisone conservent leurs précautions ; l’OFSP privilégie une alternative adaptée pour la prophylaxie pendant la grossesse. L’OFSP et la FI ciprofloxacine diffèrent pour l’allaitement, ce qui demande une décision documentée du prescripteur et non une fausse équivalence [S5, S8, S16, S18–S21].</p><p>Foie, rein, âge avancé et interactions influencent la sécurité. Rimactan est contre-indiqué par sa FI si la clairance de la créatinine est inférieure à25ml/min et en insuffisance hépatique sévère. Le produit ceftriaxone a des limites propres chez le nouveau-né et en insuffisance rénale préterminale ; ces règles ne se transposent pas à toutes les molécules [S19–S21].</p><p>Les informations de classification et de santé publique sont datées. Aucune disponibilité, prise en charge d’assurance ou obligation professionnelle individuelle2026 n’est déduite du diagnostic seul ; l’équipe applique les règles suisses courantes avec les services compétents [S1, S8, S9].</p>''','La population et la formulation font partie de chaque prescription. L’urgence vitale et les précautions du suivi ne sont pas opposées [S4, S5, S16].'))
S.append(sec(14,'Critères et pièges de raisonnement','''<p><b>Critères formels.</b> E35* requiert une maladie causale classée ailleurs et une manifestation endocrine documentée ; ce n’est pas un diagnostic étiologique autonome. La crise est clinique : les guides décrivent hypotension/choc avec symptômes compatibles, mais aucune anomalie biologique isolée ne doit devenir une condition obligatoire retardant le traitement [S1–S6].</p><p><b>Paramètres.</b> Les seuils matinaux150/300nmol/L du guide britannique concernent une population et une méthode définies ; ils ne remplacent pas l’évaluation d’un malade en choc ni les références d’un autre laboratoire. Les doses adultes, pédiatriques, de traitement infectieux et de prophylaxie gardent indication, voie et intervalle [S5, S7, S8, S16, S19–S21].</p><p><b>Pièges.</b> Attendre une pigmentation ou une hyperkaliémie ; attendre le test de stimulation ; appliquer100mg à tout nouveau-né ; additionner dose à l’âge et dose au poids ; confondre125/250mg de prophylaxie et traitement de méningite ; oublier l’induction par rifampicine ; arrêter un remplacement vital pour éviter une interaction au lieu de revoir le choix du médicament [S4–S8, S16, S19–S21].</p><p><b>Autres pièges.</b> Conclure tuberculose sur image ou granulomes seuls ; interpréter86décès sélectionnés comme une létalité ; conclure absence de déficit bilatéral sur une série sans tests hormonaux ; imposer chirurgie à toute hémorragie ; transférer un schéma pulmonaire court à une localisation thyroïdienne sans expertise [S9–S15].</p>''','Une donnée n’a de sens qu’avec sa méthode, sa population et sa question. Expliquer l’incertitude prépare une meilleure décision [S4, S5, S9, S10].'))
css='''[data-e35-table="1"]{font-size:inherit!important;display:block;max-width:100%;overflow-x:auto}[data-e35-table="1"] th,[data-e35-table="1"] td{font-size:inherit!important;min-width:9em}[data-e35-frame]{position:relative}[data-e35-frame] img{display:block;max-width:100%;height:auto}[data-e35-marker]{position:absolute;background:#123d4e;color:white;border:2px solid white;border-radius:50%;padding:1px 4px;font-weight:bold;font-size:clamp(8px,1vw,12px);line-height:1.2}[data-e35-pin="1"]{left:9%;top:40%}[data-e35-pin="2"]{left:14%;top:57%}[data-e35-pin="3"]{left:39%;top:30%}[data-e35-pin="4"]{left:56%;top:58%}'''
head='<template id="ch-E35"><div class="chap"><style>'+css+'</style><div class="chap-head"><div class="code">E35* · E35.0*, E35.1*, E35.8* · Endocrinologie et métabolisme</div><h1>Anomalies endocriniennes au cours de maladies classées ailleurs</h1><span class="status">Relecture Sol du 2 novembre2026 · Sources suisses et européennes · Auto-relecture, sans validation médicale humaine</span></div><div class="tabs ui" role="tablist">'
for i,(p,t) in enumerate([('pA','Pathologie et prise en charge'),('pE','Examens complémentaires'),('pS','Sciences fondamentales spécialisées'),('pP','Pharmacologie')]):head+=f'<button role="tab" aria-controls="{p}" data-p="{p}" aria-selected="{str(i==0).lower()}">{t}</button>'
head+='</div><div class="panel" id="pA"><nav class="toc ui"><b>Plan du cours</b><ol>'+''.join(f'<li><a href="#e35-{i+1}">{re.sub("<[^>]+>","",s[s.index("</span>")+7:s.index("</h2>")])}</a></li>' for i,s in enumerate(S))+'</ol></nav><div class="chap-body">'
pager='<div class="pager ui"><button class="prev">← Partie précédente</button><span></span><button class="next">Partie suivante →</button></div>'
refs='<div class="src"><h3>Sources effectivement consultées</h3><ul data-justification-sources="1">'
for x in ledger:refs+=f'<li><a data-reference-source="1" href="{html.escape(x["url"],quote=True)}" target="_blank" rel="noopener">[{x["id"]}] {html.escape(x["titre"])}</a> — {html.escape(x["version_annee"])}. {html.escape(x["section_page"])}. Limites : {html.escape(x["limites"])}</li>'
refs+='</ul><p>Audit différé — auto-relecture par intelligence artificielle, distincte d’une validation médicale humaine. Sources intégrales en cache externe ; texte public par paraphrases, références et limites.</p></div>'
E=[]
E.append(sec('e-1','Choisir l’examen qui change la décision',table(['Question','Examen orienté','Limite'],[['Une crise impose-t-elle de traiter ?','Clinique, circulation, conscience, glycémie et ionogramme.','Le traitement ne dépend pas d’une anomalie obligatoire du potassium ou d’une imagerie.'],['Quelle réserve après stabilisation ?','Cortisol et signal corticotrope dans conditions connues, puis stimulation si indiquée.','Heure, méthode, protéines de transport et traitement reçu modifient le résultat.'],['Atteinte glandulaire, hémorragie ou masse ?','Imagerie surrénalienne selon contexte.','Une image n’identifie pas seule le germe ni toute perte de réserve.'],['Quelle cause thyroïdienne ?','Échographie, prélèvement pertinent et microbiologie.','Image et granulomes ne sont pas spécifiques du complexe tuberculeux.']])+'''<p>Si le patient est instable, les prélèvements utiles peuvent précéder la première dose seulement s’ils ne retardent pas les soins. Documenter ensuite la dose, la voie et l’heure de l’hydrocortisone : un dosage postérieur n’est pas un résultat basal non traité [S4–S7, S10].</p>''','La question précède le test. La réanimation et le traitement causal ne sont pas suspendus pour obtenir une valeur parfaite [S4–S8].'))
E.append(sec('e-2','Cortisol et ionogramme : contexte et méthode','''<p>Le cortisol matinal est interprété avec l’état clinique et la méthode. Les repères150/300nmol/L du guide britannique s’adressent aux personnes d’au moins un an avec immunodosages modernes, dans la démarche diagnostique prévue. Chez le nourrisson de moins d’un an, le guide demande une interprétation pédiatrique spécifique ; en urgence, on n’attend pas le lendemain matin [S4, S5].</p><p>Une hormone adrénocorticotrope élevée face à un cortisol insuffisant oriente une atteinte primaire ; un signal bas ou inadapté peut être central ou iatrogène. Le déficit minéralocorticoïde est exploré par rénine, aldostérone et électrolytes. Les seuils et conditions du laboratoire comptent ; potassium normal et absence de pigmentation restent possibles en aigu [S4, S6, S10].</p><p>Les œstrogènes oraux et les protéines porteuses modifient le cortisol total. Le guide britannique prévoit, pour un test électif, des mesures particulières après certains traitements ; cela ne justifie pas de retarder une prise en charge urgente. Une réponse stimulée se lit avec le seuil propre à l’essai, pas avec une valeur copiée sans contexte [S5, S10].</p>''','Le résultat doit garder son heure, sa méthode et l’exposition médicamenteuse. Aucun seuil stable ne neutralise un tableau de crise [S4, S5, S10].'))
E.append(sec('e-3','Imagerie, tissus et microbiologie','''<p>Le scanner ou la résonance magnétique peuvent montrer hémorragie, nécrose, infiltration ou calcifications. Une calcification peut persister après une maladie ancienne et n’est pas une preuve d’infection active. Une masse hémorragique sous-jacente peut nécessiter une évaluation endocrine et oncologique spécialisée, souvent après stabilisation [S9, S10, S14].</p><p>La recherche d’un germe exige un prélèvement adapté au site et à la question : culture, amplification ciblée, examen histologique et recherche de résistances selon le contexte. Les résultats sont confrontés à l’exposition et à l’imagerie, sans transformer l’absence de lésion pulmonaire en exclusion d’une atteinte thyroïdienne [S9, S12, S13].</p><p>La revue de33cas de tuberculose thyroïdienne avec abcès comporte des diagnostics parfois fondés sur histologie ou coloration de bacilles seuls. Leurs résultats n’ont pas tous le même niveau de confirmation. Cela explique pourquoi « granulomes compatibles » et « identification du complexe tuberculeux avec sensibilité » ne sont pas deux conclusions identiques [S12].</p>''','Le prélèvement doit prouver ce que l’on cherche. La morphologie, l’espèce et la sensibilité thérapeutique sont trois informations différentes [S9, S12].'))
quizzes=[('Une personne fébrile est en choc, avec vomissements et suspicion de crise surrénalienne. Quelle conduite ?','Prélèvements si cela ne retarde pas les soins, hydrocortisone parentérale, soutien circulatoire et traitement de la cause en parallèle.','Attendre le test de stimulation pour éviter de perturber les dosages.','La crise est urgente et clinique ; les tests peuvent être complétés après stabilisation. Aucun examen ne doit retarder le remplacement nécessaire [S4–S8].'),('Un nouveau-né est suspect de crise. Peut-on recopier100mg du protocole adulte ?','Non ; utiliser le protocole pédiatrique adapté à l’âge corrigé/poids et à l’état, sans additionner les options.','Oui ;100mg est une dose uniforme pour tous les âges et toutes les formulations.','Le protocole britannique propose des options pédiatriques d’âge ou de poids, distinctes de l’adulte. La mention FI25mg/j n’est pas un bolus universel [S4, S7, S16].'),('Une masse thyroïdienne est présente avec fonction hormonale normale. Que conclure ?','La fonction conservée n’exclut ni infection ni tumeur ; caractériser la masse et orienter les prélèvements.','La fonction normale exclut toute tuberculose thyroïdienne.','La sécrétion et l’étiologie d’une masse sont deux questions distinctes ; l’imagerie et les prélèvements gardent leur place [S12, S13, S25].'),('Une prophylaxie méningococcique est nécessaire chez une personne allaitante. Les sources divergent pour ciprofloxacine. Que faire ?','Confronter directive OFSP et FI du produit, choisir une option adaptée et documenter la décision sans abandonner la prophylaxie indiquée.','Présenter toutes les molécules de la directive comme autorisées sans réserve dans chaque FI.','Le document OFSP2025permet les molécules citées pendant allaitement, mais la FI Ciproxine conserve une interdiction. Les textes et la population doivent rester distincts ; le prescripteur adapte le choix [S8, S19–S21].')]
q=''
for i,(case,good,bad,fb) in enumerate(quizzes,1):q+=f'<div class="quiz ui"><p><b>Cas fictif {i}.</b> {case}</p><button data-ok="1">{good}</button><button data-ok="0">{bad}</button><p class="fb" hidden>{fb}</p></div>'
E.append(sec('e-4','Quatre exercices de raisonnement',q,'Urgence, population, fonction et statut d’un produit sont quatre questions qui ne se remplacent pas [S4, S7, S8, S16, S21].'))
semio=[
('normal','Normal : fonction et réserve','''Le cortex surrénalien produit cortisol, minéralocorticoïdes et précurseurs androgéniques ; la médulla est un autre compartiment. La thyroïde sécrète des hormones iodées depuis une architecture folliculaire. Une fonction suffisante au repos ne décrit pas toujours la réponse nécessaire lors d’une maladie aiguë. Organe visible, fonction hormonale et réserve sont trois dimensions [S4, S23, S25].'''),
('signs','Signes et symptômes','''Fatigue, amaigrissement, nausées, douleur abdominale et hypotension sont peu spécifiques. Une pigmentation et une envie de sel peuvent accompagner une insuffisance primaire chronique, mais manquer en aigu. Fièvre, purpura, altération de conscience ou dégradation circulatoire changent l’urgence. Une masse cervicale peut rester indolore et la fonction thyroïdienne peut être conservée [S4, S5, S8, S10, S12].'''),
('mechanisms','Du mécanisme au signe','''Le manque de cortisol compromet la réponse au stress et favorise vasoplégie et déséquilibre métabolique. La perte d’aldostérone peut ajouter une perte sodée et une déplétion ; un déficit central ne touche pas toujours cette régulation. Infection et hémorragie peuvent léser les glandes, tandis qu’une infection peut aussi simplement déclencher une crise sur déficit antérieur. La distinction choisit les examens et le suivi [S4, S6, S10, S14].'''),
('examination','Examen expliqué','''Décrire conscience, perfusion, respiration, pression, pouls, température et déshydratation. Rechercher purpura et signes infectieux, abdomen douloureux, pigmentation chronique et symptômes orthostatiques si l’état permet cet examen. Au cou, décrire masse, adénopathies, voix et déglutition. La dégradation clinique impose action sans attendre un examen complet électif [S4, S5, S8, S12, S24].'''),
('interpretation','Interprétation contextualisée','''Aucun signe isolé ne confirme toute crise ou son étiologie. Potassium normal, absence de pigmentation ou de fièvre ne suffisent pas à exclure une atteinte aiguë. Les valeurs de cortisol gardent heure, méthode et traitement. Une image bilatérale augmente la vigilance mais ne quantifie pas à elle seule la réserve ; fonction thyroïdienne normale n’exclut pas masse infectieuse [S4, S5, S10–S12].'''),
('differentials','Différentiels utiles','''Choc septique, hypovolémie, défaillance endocrine et autres urgences peuvent se superposer. Les déficits centraux, médicamenteux, auto-immuns ou congénitaux ne sont pas automatiquement E35. Une masse thyroïdienne confronte infection, inflammation et tumeur. Un prélèvement granulomateux doit être corrélé à la microbiologie et au contexte, pas seulement à une réputation de rareté [S2, S4, S6, S9, S12].'''),
('urgency','Urgence et orientation','''Instabilité circulatoire, trouble de conscience, hypoglycémie, vomissements empêchant la prise orale, purpura ou gêne respiratoire commandent une évaluation urgente. Hydrocortisone si crise suspectée, soutien circulatoire et traitement infectieux indiqué se font en parallèle. Les doses d’adulte, de nouveau-né et de contact sain ne s’échangent pas ; les prélèvements ne doivent pas retarder les soins [S4–S8, S16, S19].'''),
('limits','Limites et relation de soin','''La clinique déclenche l’action, mais ne prouve pas toujours l’agent ni le niveau de la lésion. Les tests sont complétés après stabilisation, avec limites du prélèvement et de la méthode. Expliquer le plan de suivi et entraîner réellement au kit d’urgence sont nécessaires ; un texte appris ne garantit pas son application. Aucun score E35 universel ou certification clinique n’est revendiqué [S4–S7, S10, S24].'''),
('sources','Sources, populations et portée','''Sources suisses de classification, pédiatrie, médicament, infection invasive et tuberculose sont confrontées aux guides européens et aux synthèses. Les protocoles britanniques, l’addendum suisse2017et les FI datées ne sont pas fusionnés en une règle nouvelle. Les cas ou séries sélectionnés ne deviennent pas des risques suisses ; liens ci-dessous vers les sources effectivement lues [S1–S10, S16–S22, S24].''')]
units={};units['semio']='<section class="ilot" id="e35-s-semio-cours"><h3>Pour la leçon : quelle est la sémiologie fondamentale et analytique ?</h3>'+''.join(f'<section class="ilot" id="e35-semio-{k}" data-semiology="{k}"><h3>{title}</h3><p>{body}</p></section>' for k,title,body in semio)+'</section>'
imgroot=R/'assets/img/e35/alpha/codex';imgroot.mkdir(parents=True,exist_ok=True);(D/'figures').mkdir(exist_ok=True);orig=Path('/tmp/medina-source-cache/endocrinologie/E25/adrenal-openstax2013.jpg');shutil.copyfile(orig,imgroot/orig.name);shutil.copyfile(orig,D/'figures'/orig.name)
def humanfigure(kind):
 return f'''<figure id="e35-{kind}-figure"><div data-e35-frame="{kind}"><img src="assets/img/e35/alpha/codex/adrenal-openstax2013.jpg" alt="Original humain : surrénale au-dessus du rein, coupe corticale et médullaire, micrographie et régions fonctionnelles ; planche normale." width="1102" height="316"><span data-e35-marker="1" data-e35-pin="1">1</span><span data-e35-marker="1" data-e35-pin="2">2</span><span data-e35-marker="1" data-e35-pin="3">3</span><span data-e35-marker="1" data-e35-pin="4">4</span></div><figcaption>Original humain OpenStax College, Connexions,19juin2013 ; micrographie University of Michigan Medical School ©2012. <a data-reference-source="1" href="https://commons.wikimedia.org/wiki/File:1818_The_Adrenal_Glands.jpg" target="_blank" rel="noopener">Figure historique1818</a>, <a data-reference-source="1" href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noopener">Creative Commons Attribution3.0</a>. Pixels inchangés ; repères français superposés :1surrénale au-dessus du rein ;2cortex périphérique et médulla centrale dans la coupe ;3micrographie ;4régions corticales et médullaire indiquées par la planche. Même original utilisé dans anatomie et histologie, pas deux originaux différents. Image normale, pas lésion infectieuse ou hémorragique. Grossissement optique d’origine204×, pas mesure d’écran ; coloration non précisée dans la notice lue. Labels anglais complétés par légende française, essentielle sur petit écran [S4, S23].</figcaption></figure>'''
units['anat']=sec('s-anat-cours','Anatomie : un organe, deux compartiments','''<p>Les surrénales se situent au-dessus des reins et comportent une capsule, un cortex périphérique et une médulla centrale. Leur position explique qu’une lésion puisse se manifester par douleur abdominale, lombaire ou du flanc, tout en restant non palpable à l’examen habituel. L’imagerie précise le siège, l’étendue et les rapports quand l’état le permet [S10, S23].</p><p>La vascularisation est riche et le drainage veineux est organisé autour d’une veine principale. Les mécanismes de congestion, thrombose et hémorragie dans certaines situations de stress ou de coagulation rendent la glande vulnérable ; cette explication physiopathologique ne signifie pas que toute glande très vascularisée saigne ou que tout hématome soit septique [S10].</p>'''+humanfigure('anat')+'''<p>Le cortex et la médulla sont distincts par développement, organisation et hormones. Une insuffisance corticale ne se confond donc pas avec une absence de toute activité médullaire. La perte corticale bilatérale expose davantage au déficit qu’une lésion unilatérale avec glande opposée fonctionnelle ; une atteinte controlatérale discrète ou une maladie préexistante peut toutefois modifier cette règle pratique [S4, S10, S23].</p><p>La planche humaine normale donne les compartiments, pas un diagnostic individuel d’hémorragie, d’infection ou de réserve. Les repères français complètent les labels originaux et ne dessinent aucune nouvelle anatomie. Les rapports vasculaires détaillés ne sont pas représentés comme s’ils étaient mesurés sur la micrographie [S10, S23].</p><p>La thyroïde est un autre organe : elle siège devant la trachée, sous le larynx, avec deux lobes reliés par un isthme. Une masse cervicale et des adénopathies se localisent par examen et échographie ; une extension ou une compression modifie la prise en charge. La topographie thyroïdienne ne détermine pas seule si la cause est tuberculeuse, pyogène ou tumorale [S12, S13, S25].</p>''','Topographie, vascularisation et compartiments expliquent les questions de l’examen. La planche normale ne démontre pas la maladie du patient [S4, S10, S23].')
units['histo']=sec('s-histo-cours','Histologie : du compartiment normal à la lésion','''<p>Le cortex surrénalien est organisé en régions glomérulée, fasciculée et réticulée, associées à des productions stéroïdiennes différentes. La médulla contient des cellules neuroendocrines produisant des catécholamines. Cette organisation explique qu’un dosage de cortisol, un profil minéralocorticoïde et une recherche de sécrétion médullaire ne répondent pas à la même question [S4, S23].</p><p>La micrographie incluse dans l’original montre une structure normale. Le grossissement optique annoncé par la source n’est pas un grossissement d’écran ni une calibration permettant de mesurer des cellules depuis cette page. La légende repère la coupe et ses régions ; aucune lésion tuberculeuse, nécrose ou hémorragie n’y est inventée [S23].</p>'''+humanfigure('histo')+'''<p>Dans une infection granulomateuse, l’architecture peut être remplacée par inflammation et nécrose. Des granulomes et une nécrose caséeuse sont compatibles avec certaines infections, mais leur présence ne remplace pas la recherche du microorganisme et de sa sensibilité. Une coloration de bacilles acido-alcoolo-résistants ne distingue pas à elle seule toutes les espèces mycobactériennes [S9, S12, S14].</p><p>La thyroïde normale comporte des follicules épithéliaux entourant un colloïde riche en thyroglobuline. Une maladie locale peut perturber ce tissu sans abolir immédiatement toute sécrétion hormonale. Une masse avec fonction conservée mérite donc encore une caractérisation ; la biologie normale n’est pas une biopsie négative [S12, S13, S25].</p><p>La représentativité du prélèvement est centrale. Une aspiration pauvre, une région nécrotique ou une zone non atteinte peut ne pas répondre à la question. Les cas publiés de tuberculose thyroïdienne n’ont pas tous une confirmation au même niveau : histologie, coloration, culture et amplification moléculaire apportent des preuves différentes [S12, S13].</p><p>Enfin, une lésion hémorragique peut masquer un processus sous-jacent. Le compte rendu, les images et le contexte sont confrontés avant de conclure à une simple conséquence infectieuse. Cette démarche peut conduire à surveillance ou à prélèvement/traitement spécialisé, sans chirurgie automatique de toute glande anormale [S10].</p>''','L’architecture, le site prélevé et la preuve microbiologique se complètent. Une image normale pédagogique ne classifie pas une lésion réelle [S9, S10, S12].')
units['physio']=sec('s-physio-cours','Physiologie : réserve et réponse au stress','''<p>L’hypothalamus, l’hypophyse et le cortex surrénalien forment un axe de régulation. Le signal hypothalamique stimule la sécrétion hypophysaire de l’hormone adrénocorticotrope, qui stimule la production corticale de cortisol. Celui-ci exerce un rétrocontrôle. Une insuffisance peut donc venir de la glande, du signal central ou d’une suppression après exposition médicamenteuse [S4, S6, S23].</p><p>Le cortisol contribue à mobiliser les substrats énergétiques et à maintenir une réponse appropriée au stress. Le manque peut se manifester par faiblesse, hypoglycémie, intolérance à une maladie intercurrente et défaillance circulatoire. Ces signes ne sont pas spécifiques, et une infection peut produire des symptômes semblables ; les deux mécanismes peuvent s’ajouter au lieu de s’exclure [S4–S6].</p><p>L’aldostérone répond surtout au système rénine-angiotensine et au potassium. Elle favorise la conservation sodée et l’excrétion potassique. Une atteinte primaire peut donc produire un déficit glucocorticoïde et minéralocorticoïde, tandis qu’un déficit central conserve généralement la seconde régulation. Une hyponatrémie isolée ne suffit pas à identifier le niveau de la lésion [S4, S6, S23].</p><p>À doses de stress, l’hydrocortisone a aussi une activité minéralocorticoïde. Cela explique pourquoi le plan de crise n’ajoute pas automatiquement un triplement de fludrocortisone. Le retour au remplacement chronique et son ajustement sont guidés par état clinique, pression et électrolytes, pas par une règle de multiplication appliquée à toutes les hormones [S4, S7, S10, S18].</p><p>La réserve peut être insuffisante seulement lorsque les besoins augmentent. Vomissements, mauvaise absorption ou augmentation de clairance par un médicament peuvent aggraver le déficit même sans nouvelle destruction anatomique. Distinguer ces mécanismes aide à traiter le déclencheur et à prévenir la prochaine crise [S4, S6, S16].</p><p>La physiologie thyroïdienne illustre une autre séparation : la production d’hormones peut rester suffisante malgré une lésion focale infectieuse. Fonction et nature de la masse restent deux questions. Dans les deux glandes, un chiffre normal à un moment ne remplace pas l’évolution et la question clinique [S12, S25].</p>''','Le besoin augmente pendant le stress, mais les hormones n’ont pas toutes la même régulation ni le même ajustement [S4, S6, S7].')
units['bioch']=sec('s-bioch-cours','Biochimie : mesurer le bon signal','''<p>Le cortisol circulant, son signal hypophysaire et les paramètres minéralocorticoïdes représentent des étages différents. Un cortisol insuffisant avec un signal corticotrope élevé oriente la glande ; un signal bas ou inadapté peut orienter le centre ou une suppression médicamenteuse. Le prélèvement et sa méthode restent indispensables à l’interprétation [S4–S6].</p><p>Le cortisol total dépend notamment des protéines de transport. Les œstrogènes oraux peuvent l’augmenter sans que la même variation reflète une modification identique de réserve. Le guide britannique prévoit des conditions particulières pour un bilan électif ; dans une urgence, ces interférences sont documentées sans retarder le traitement. Un résultat post-hydrocortisone n’est pas une valeur basale intacte [S5, S10].</p><p>Les seuils de stimulation varient entre méthodes ; les anciens repères ne se transportent pas automatiquement à tous les essais modernes. Les valeurs matinales150/300nmol/L du guide britannique sont des repères dans un parcours et une population, pas un test universel à toute heure ni en choc. Chez le nourrisson, une lecture spécialisée est requise [S4, S5, S10].</p><p>Les interactions changent aussi la quantité de médicament disponible. La rifampicine induit des voies métaboliques et peut réduire l’exposition à l’hydrocortisone ; sa mise en route ou son arrêt demande réévaluation, sans facteur multiplicatif unique déduit de cette propriété. Une mauvaise absorption digestive produit un autre mécanisme de sous-remplacement [S6, S16, S20].</p><p>Dans la thyroïde, l’iodure et les résidus tyrosine de la thyroglobuline participent à la synthèse des hormones iodées dans l’architecture folliculaire. Une infection peut toucher la structure sans abolir immédiatement la sécrétion. Les hormones circulantes ne sont donc pas une identification microbiologique du germe [S12, S25].</p><p>Enfin, la microbiologie mesure encore autre chose : amplification ciblée, culture et sensibilité répondent à identité et résistance. Une histologie compatible n’est pas une analyse génétique du pathogène, et la détection d’une infection ne quantifie pas à elle seule la réserve endocrine. La décision réunit ces informations [S9, S12].</p>''','Résultat hormonal, exposition au médicament et preuve du germe ont des objets différents ; l’un ne remplace pas les autres [S5, S9, S16].')
units['gene']=sec('s-gene-cours','Génétique et immunologie : hôte, pathogène et terrain','''<p>Les anomalies endocriniennes acquises dans une infection ne sont pas toutes des maladies génétiques de l’hôte. Chez l’enfant, une anomalie congénitale peut être révélée par une infection sans que l’infection ait créé le déficit enzymatique. La revue suisse rappelle de nombreuses causes héréditaires de déficit primaire ou central ; elles servent ici de différentiels et ne sont pas reclassées automatiquement E35 [S2, S4].</p><p>Un déficit de l’hôte peut modifier le risque infectieux. Le document suisse sur le méningocoque mentionne notamment asplénie et anomalies du complément, tout en rappelant que des formes graves surviennent chez des personnes auparavant saines. Cette association ne justifie pas un test génétique universel de chaque patient ni une conclusion héréditaire à partir d’un seul épisode septique [S8].</p><p>Le terrain immunitaire intervient aussi dans les infections granulomateuses. Immunosuppression, maladie sous-jacente, sites atteints et exposition orientent les recherches. La présence d’une masse thyroïdienne sans signes pulmonaires ne suffit pas à conclure que l’hôte est immunodéficient ; la revue d’abcès thyroïdiens comportait de nombreux patients sans immunodépression rapportée [S9, S12, S14].</p><p>Il faut distinguer génétique de l’hôte et analyse du microorganisme. Une amplification peut identifier le complexe tuberculeux et rechercher des résistances selon la méthode ; ce résultat n’est pas un diagnostic constitutionnel du patient. La culture et l’antibiogramme complètent la stratégie, et les performances dépendent de la qualité du prélèvement [S9, S12].</p><p>Les glucocorticoïdes ont des effets immunologiques dont l’intensité dépend de l’exposition. Remplacement indispensable et traitement immunosuppresseur prolongé ne sont pas une même indication, même si le produit a le même nom. Une infection sévère nécessite traitement étiologique et surveillance ; la crainte de l’immunosuppression ne doit pas retarder un remplacement vital dans une crise suspectée [S4–S6, S16, S18].</p><p>Enfin, les observations d’autopsie et les associations de cas sont différentes d’une mesure prospective du risque. Des agents variés peuvent accompagner le tableau de Waterhouse-Friderichsen ; le mécanisme et l’identification doivent rester documentés. Aucun variant unique ni signature immunitaire ne sont inventés pour toute la catégorie E35 [S8, S15].</p>''','Hôte, agent et médicament influencent le tableau par des mécanismes différents ; une infection révélatrice n’est pas forcément la cause initiale du déficit [S4, S6, S8, S9].')
bridges={
'semio':('Reconnaître les signes de gravité avant d’exiger un résultat confirmatoire.','Prélever si cela ne retarde pas les soins ; compléter après stabilisation.','Traiter le déclencheur et le déficit nécessaire en parallèle.','Signe et gravité','Mécanisme et prélèvement utile','Soins puis confirmation','S4, S5, S8'),
'anat':('La localisation et les compartiments expliquent symptômes et réserve.','L’imagerie précise l’atteinte et la glande opposée.','Le choix d’un geste dépend du saignement, de la stabilité et de la cause.','','','','S4, S10, S23'),
'histo':('Une fonction conservée n’exclut pas une lésion focale.','Tissu, culture et amplification apportent des preuves différentes.','Éviter une chirurgie automatique sans question diagnostique ou thérapeutique.','','','','S9, S10, S12'),
'physio':('Une réserve insuffisante peut se révéler seulement lors du stress.','Le niveau de l’atteinte guide les mesures complémentaires.','Stress glucocorticoïde et remplacement minéralocorticoïde ont des règles distinctes.','Réserve et besoin de stress','Cortisol et circulation','Remplacement selon le contexte','S4, S6, S7'),
'bioch':('Un résultat dépend de son heure, de son traitement et de sa méthode.','L’identité du germe ne se lit pas sur le cortisol.','Interactions et absorption modifient le remplacement sans dose universelle nouvelle.','Signal et conditions','Mesure contextualisée','Décision et réévaluation','S5, S9, S16'),
'gene':('Une infection peut révéler une cause congénitale ou un terrain sans être cette cause.','Distinguer analyses de l’hôte et recherches sur le microorganisme.','Remplacement vital, anti-infectieux et immunosuppression ne sont pas interchangeables.','Hôte et agent distincts','Preuve ciblée','Traitement et prévention adaptés','S4, S8, S9, S16')}
for k,(cl,ex,tr,a,b,c,ss) in bridges.items():
 bridge=f'<div class="key"><p><b>Science → clinique.</b> {cl} [{ss}]</p><p><b>Science → examen.</b> {ex} [{ss}]</p><p><b>Science → traitement.</b> {tr} [{ss}]</p><p><b>À retenir.</b> La fonction, la cause et la gravité sont confrontées, sans se remplacer.</p></div>'
 if a:bridge+=logical(a,b,c,'Enchaînement de raisonnement sans anatomie ni score individuel ['+ss+'].')
 if k=='semio':
  at=units[k].index('</h3>')+5;units[k]=units[k][:at]+bridge+units[k][at:]
 else:units[k]=bridge+units[k]
sc='<div class="panel" id="pS" hidden><div class="sci-bar ui" role="tablist">'
labels=[('semio','Sémiologie fondamentale et analytique'),('anat','Anatomie'),('histo','Histologie'),('physio','Physiologie'),('bioch','Biochimie'),('gene','Génétique et immunologie')]
for i,(k,label) in enumerate(labels):sc+=f'<button id="e35-tab-{k}" role="tab" aria-controls="e35-s-{k}" data-s="e35-s-{k}" aria-selected="{str(i==0).lower()}">{label}</button>'
sc+='</div><div class="chap-body sci-body">'
for i,(k,label) in enumerate(labels):sc+=f'<div class="sci" role="tabpanel" aria-labelledby="e35-tab-{k}" id="e35-s-{k}"'+(' hidden' if i else '')+'>'+units[k]+'</div>'
sc+='</div>'+pager+'</div>'
P=[]
hydrotable=table(['Population / source','Repère de protocole','Produit et limite'],[['Adulte, NICE2024/ESE2024','100mg intraveineux ou intramusculaire immédiatement ; puis200mg/24h en perfusion ou50mg toutes les6h selon protocole.','Solu-Cortef FI octobre2025 : IV préférée en urgence ;100mg en au moins30secondes.'],['Enfant, option âge BSPED2023','Moins1an25mg ;1–5ans50mg ;dès6ans100mg, IM/IV.','Option d’âge, pas addition à la dose au poids.'],['Enfant, option poids BSPED2023','Après28jours corrigés :2mg/kg IV, maximum100mg ; avant28jours corrigés :4mg/kg IV.','Fréquence et diminution ensuite selon état et protocole pédiatrique ; ne pas recopier le bolus adulte.'],['FI suisse générale pédiatrique','Adaptation à l’état/réponse ; mention de minimum25mg/j.','Ce minimum journalier n’est pas un bolus universel ; protocole pédiatrique et produit confrontés par l’équipe.']])
P.append(sec('p-1','Hydrocortisone d’urgence : voie et population',f'''<p>Solu-Cortef est une poudre et un solvant pour injection/perfusion. Les présentations Act-O-Vial100mg et250mg ont chacune2ml de solvant, avec quantités différentes de principe actif. La voie intrathécale, réservée à des indications particulières, n’est pas une voie de crise ; l’épidurale est contre-indiquée. L’urgence privilégie la voie intraveineuse et la technique exacte de la FI [S16].</p>'''+hydrotable+f'''<p>Le {w('hydrocortisone','détail des options pédiatriques et du produit')} distingue le schéma d’âge et celui au poids. Le tableau suisse de Flück2023 et le consensus britannique ont des limites d’âge différentes : on applique le protocole validé pour la population du centre, sans composer une nouvelle règle. La fluidothérapie, le glucose et les électrolytes sont surveillés en parallèle [S4, S7, S16].</p><p>Allergie, contre-indication de l’intramusculaire en purpura thrombopénique idiopathique, précautions hépatiques et interactions sont conservées. La FI ne demande pas d’adaptation rénale, mais l’ensemble du malade reste surveillé. La nécessité vitale de substitution dans une crise suspectée n’est pas annulée par les précautions d’une corticothérapie prolongée [S4, S5, S16].</p>''','Dose initiale, voie, concentration et population sont vérifiées ensemble. Pas de100mg uniforme chez le nouveau-né [S4, S7, S16].'))
P.append(sec('p-2','Relais oral et déficit minéralocorticoïde',table(['Produit suisse daté','Repère de FI','Surveillance / limite'],[[w('galepharm','Hydrocortisone Galepharm10mg, août2025'),'Insuffisance chronique10–20mg/j, parfois davantage ; prise(s) selon indication.','La plage10–30mg/j de l’hyperplasie congénitale n’est pas une dose E35 universelle.'],[w('fludrocortisone','Florinef0,1mg, mars2026'),'Adulte0,1mg3fois/semaine à0,2mg/j, dose courante0,1mg/j ;12–18ans comme adulte.','Pression, poids, électrolytes et rénine ; rein/foie peu étudiés.'],['Florinef,0–12ans','2–5µg/kg/j selon FI.','Repères spécialisés et FI différents ; pas transposition automatique d’une dose néonatale fixe.']])+'''<p>Le relais oral attend stabilité et absorption suffisante. Les besoins glucocorticoïdes et minéralocorticoïdes sont réévalués séparément ; on ne triple pas automatiquement Florinef en cas de fièvre. Le déficit central sans déficit aldostéronique ne reçoit pas ce produit par principe [S4–S7, S17, S18].</p><p>La FI Florinef décrit notamment hypertension sévère et autres contre-indications, risque de rétention sodée, œdèmes et hypokaliémie, et une absence de données permettant une adaptation chiffrée en atteinte rénale/hépatique. Elle réserve la grossesse aux nécessités et demande de ne pas allaiter ; le suivi spécialisé maintient le remplacement indispensable en choisissant une stratégie adaptée [S5, S18].</p>''','Le relais et les deux remplacements sont individualisés. Le contrôle de l’infection ne permet pas d’arrêter automatiquement les hormones [S4, S5, S17, S18].'))
P.append(sec('p-3','Ceftriaxone : malade et contact sain',table(['Situation','Repère daté','Limite'],[['Maladie invasive adulte','FI Rocephin juin2025 : généralement1–2g/j, jusqu’à4g/j en sévère ; addendum SSI2017pour méningite empirique :2×2g.','Schéma hospitalier choisi selon syndrome, germe et protocole courant ; pas petite dose de prophylaxie.'],['Méningite de l’enfant','FI :100mg/kg/j, maximum4g, puis adaptation au germe/sensibilité.','Ne pas appliquer sans les restrictions néonatales et la voie/temps de perfusion appropriés.'],['Prophylaxie OFSP2025, contact sain','≤12ans125mg IM unique ; grossesse et alternative>12ans250mg IM unique.','Conduite de santé publique distincte de l’indication infectieuse et du schéma de traitement FI.']])+f'''<p>{w('ceftriaxone','Rocephin, juin2025')} distingue préparations intraveineuses et intramusculaire avec lidocaïne. Une solution contenant de la lidocaïne ne doit jamais être injectée dans une veine. Les doses pédiatriques élevées sont perfusées selon la FI ; les contre-indications de la lidocaïne s’ajoutent pour la préparation intramusculaire [S19].</p><p>Prématuré jusqu’à41semaines postmenstruelles : contre-indication ; nouveau-né jusqu’à28jours ayant besoin ou susceptible d’avoir besoin de calcium intraveineux : contre-indication ; hyperbilirubinémie néonatale : ne pas traiter selon FI. Le schéma100mg/kg de méningite enfant n’annule pas le maximum50mg/kg/j du nouveau-né jusqu’à14jours et les autres restrictions néonatales [S19].</p><p>En insuffisance rénale avec clairance inférieure à10ml/min, la FI limite à2g/j, de même chez le dialysé ; les atteintes rénale et hépatique combinées requièrent surveillance. Allergie, hémolyse, réactions cutanées, colite et encéphalopathie font partie des risques. Les choix d’urgence sont faits par l’équipe pour la population réelle [S19].</p>''','Deux doses très différentes peuvent avoir le même nom de produit : toujours préciser si l’on traite une infection ou un contact sain [S8, S19, S22].'))
P.append(sec('p-4','Rifampicine : prophylaxie, tuberculose et interactions',table(['Prophylaxie selon FI Rimactan octobre2023','Dose orale','Durée'],[['Adulte/ado>12ans et poids>60kg','600mg toutes les12h','2jours, quatre doses'],['Dès1mois, enfant jusqu12ans ou ado>12ans avec poids<60kg','10mg/kg toutes les12h, sans dépasser dose adulte','2jours, quatre doses'],['Moins1mois','5mg/kg toutes les12h','2jours, quatre doses']])+f'''<p>Le protocole OFSP2025 décrit10mg/kg par dose, maximum600mg, dès un mois, et5mg/kg avant un mois. Les bornes de poids du libellé FI ne sont pas élargies arbitrairement au point exact60kg ; l’équipe applique le protocole adapté. Une forme compatible avec le jeune âge est nécessaire, pas une gélule imposée [S8, S20].</p><p>{w('rifampicine','Rimactan, octobre2023')} ne traite pas une méningite méningococcique manifeste. Pour la tuberculose, la rifampicine s’emploie en association, selon guide suisse et sensibilité. La dose et la durée de prophylaxie ne sont pas celles d’un traitement antituberculeux [S9, S20].</p><p>Contre-indication si clairance de la créatinine inférieure à25ml/min ou insuffisance hépatique sévère selon cette FI. Hépatotoxicité, interactions multiples et diminution d’efficacité de contraceptifs hormonaux sont à vérifier. L’induction peut réduire l’exposition à l’hydrocortisone : réévaluer le remplacement lors de début/arrêt sans multiplicateur universel ni interruption du traitement vital [S6, S16, S20].</p>''','Même molécule, deux indications et deux durées différentes. L’interaction peut révéler ou aggraver une insuffisance [S6, S16, S20].'))
P.append(sec('p-5','Ciprofloxacine : divergence entre protocole et FI',table(['Source et population','Schéma de prophylaxie','Portée'],[['FI Ciproxine orale août2025, adulte','500mg en dose unique.','Indication de prévention invasive explicitement listée chez adulte.'],['OFSP2025, hors grossesse','20mg/kg en dose orale unique ; maximum500mg dès1mois.','Directive pédiatrique distincte : les indications/contre-indications de croissance de la FI ne couvrent pas ce schéma comme autorisation générale.'],['Allaitement','OFSP permet les molécules citées, FI Ciproxine demande de ne pas l’utiliser.','Divergence explicite, choix spécialisé d’une option adaptée et documentation.']])+f'''<p>Le produit est {w('ciprofloxacine','Ciproxine comprimés ou suspension orale')}, pas Ciproxin HC otique. La FI réserve l’enfant à des indications et conditions particulières, et contre-indique grossesse/allaitement hors situations spéciales décrites. Le protocole OFSP n’est donc pas recopié sous la mention « dose autorisée par toute FI » ; indication, population, formulation et décision du prescripteur restent visibles [S8, S21].</p><p>Tizanidine et agomélatine concomitantes sont contre-indiquées. Tendinites/ruptures, neuropathies et autres effets graves sont décrits ; l’association aux corticostéroïdes majore notamment le risque tendineux. Chez une personne nécessitant un remplacement vital, on revoit le choix prophylactique avec l’équipe plutôt que supprimer d’office ce remplacement [S5, S8, S21].</p><p>Les cations et certains antiacides diminuent la résorption : la FI prévoit prise une–deux heures avant ou quatre heures après ces produits. L’insuffisance rénale influence les maxima journaliers de la FI ; une dose unique ne dispense pas de vérifier le terrain. Les informations Swisspeddose ajoutées à la page sont distinctes du texte d’autorisation [S21].</p>''','Une directive et une FI répondent à des questions différentes. Les désaccords doivent rester explicites, surtout en pédiatrie et allaitement [S8, S21].'))
P.append(sec('p-6','Coordonner les traitements et le suivi','''<p>Avant et pendant les soins, vérifier produit exact, quantité, voie, intervalle, indication et dernière dose absorbée. La surveillance vise pression, perfusion, glycémie, électrolytes et réponse infectieuse. Les interactions et l’évolution clinique peuvent modifier les besoins ; aucun tableau ne remplace cette réévaluation [S4–S8, S16–S21].</p><p>Une corticothérapie adjuvante d’une méningite, un remplacement de crise et un traitement immunosuppresseur prolongé ne sont pas des schémas à additionner automatiquement. L’équipe clarifie l’objectif de chaque médicament et les équivalences pertinentes. La formulation et la dose de stress sont revues lorsque l’état se stabilise [S4–S6, S16, S22].</p><p>Le suivi organise les kits, les doses disponibles et l’entraînement. Une ordonnance de sortie doit être compréhensible pour la personne, son entourage et les professionnels appelés en urgence. Les précautions de grossesse, allaitement, foie ou rein sont reprises pour le produit réellement poursuivi [S4, S5, S16–S21].</p>''','La sécurité repose aussi sur une coordination compréhensible et un plan appliqué, pas seulement sur une dose exacte sur papier [S4, S5].'))
pop('hydrocortisone','Hydrocortisone : produit et options pédiatriques',hydrotable+'''<p>Le tableau3BSPED2023propose une option d’âge ou de poids : ne pas additionner. Enfant après28jours corrigés :2mg/kg IV initial, max100mg, puis selon état ; nouveau-né avant28jours corrigés :4mg/kg IV. Lorsqu’il est stable et s’améliore, le protocole décrit1mg/kgmax50toutes les six heures chez enfant,2mg/kgchez nouveau-né, puis relais oral de maladie si toléré. Cette conduite est distincte de la FI générale et du tableau suisse2023, dont les bornes diffèrent [S4, S7, S16].</p><p>Act-O-Vial100mg et250mg ont chacun2ml de solvant : ne pas supposer la même concentration. Injection IV100mg en au moins30secondes ; intrathécal n’est pas voie de crise. La mention FI minimum25mg/j pédiatrique n’est pas un bolus25mg universel et ne constitue pas un protocole néonatal complet [S16].</p>''')
pop('galepharm','Remplacement oral : produit suisse daté','''<p>Hydrocortisone Galepharm10mg, FI août2025 : insuffisance surrénale chronique10–20mg/j, parfois davantage, doses et prises adaptées. La plage hyperplasie congénitale10–30mg/j n’est pas celle de toute E35. Le guide britannique utilise une autre plage habituelle15–25mg/j ; ne pas l’étiqueter comme dose de la FI suisse ni créer une moyenne [S5, S17].</p><p>Vomissements ou mauvaise absorption et crise imposent un autre parcours, souvent parentéral. L’arrêt du remplacement vital n’est pas une mesure de gestion d’une interaction ; la dose est réévaluée avec le prescripteur [S4–S6, S16, S17].</p>''')
pop('fludrocortisone','Déficit minéralocorticoïde et dose','''<p>Florinef comprimé0,1mg, FI mars2026 : adulte0,1mg trois fois par semaine à0,2mg/j, dose habituelle0,1mg/j ;12–18anscomme adulte ;0–12ans2–5µg/kg/j. Surveiller pression, poids, électrolytes et rénine ; pas adaptation chiffrée validée pour tout rein/foie. Le stress ne conduit pas à tripler automatiquement ce médicament [S4, S7, S18].</p><p>La FI demande de ne pas allaiter et réserve grossesse à nécessité ; le suivi spécialisé maintient une stratégie de remplacement indispensable et adaptée. Les protocoles étrangers, la FI et l’âge ne sont pas fusionnés [S5, S18].</p>''')
pop('ceftriaxone','Ceftriaxone : voie, âge et indication','''<p>Rocephin FI juin2025 : préparations intraveineuses distinctes de la forme intramusculaire avec lidocaïne ; solution lidocaïnée jamais IV. Adulte1–2g/j, jusqu’à4g/j en sévère ; addendum suisse2017méningite2×2g, protocole hospitalier à contextualiser. Enfant méningite100mg/kg/jmax4g ; le nouveau-né jusqu’à14jours garde un maximum50mg/kg/j ; de15jours à12ans, la plage usuelle est20–80mg/kg/j hors schéma spécifique, avec dose adulte si poids≥50kg [S19, S22].</p><p>Prématuré jusqu’à41semaines postmenstruelles contre-indiqué ; nouveau-né≤28jours avec besoin actuel/probable de calcium IV contre-indiqué ; hyperbilirubinémie néonatale ne pas traiter. Prophylaxie OFSP125/250mg IM unique chez contact n’est jamais la dose d’un malade invasif [S8, S19].</p>''')
pop('rifampicine','Rifampicine : indication et induction','''<p>Rimactan gélules150/300mg, FI octobre2023. Prophylaxie méningocoque :600mg toutes les douze heures deux jours chez adulte/ado>12anset>60kg ;10mg/kg par prise sans dépasser dose adulte dès un mois chez les groupes de poids/âge précisés ; avant un mois5mg/kg. OFSP présente aussi une option au poids10mg/kgmax600dès un mois ; pas élargissement arbitraire des bornes strictes du libellé [S8, S20].</p><p>Pas traitement d’une méningite manifeste ni monothérapie de tuberculose. Clairance<25ml/min ou foie sévère : contre-indications FI. Induction du métabolisme et interactions nombreuses ; hydrocortisone peut demander adaptation à début/arrêt, sans facteur unique ni arrêt d’un remplacement vital [S6, S16, S20].</p>''')
pop('ciprofloxacine','Prophylaxie : directive et autorisation du produit','''<p>Ciproxine orale FI août2025 : adulte500mgdoseunique pour prévention invasive à méningocoque. La directive OFSP2025prévoit20mg/kgdoseunique en pédiatrie, max500dès un mois, mais la FI réserve les indications avant fin de croissance et ne fournit pas une autorisation générale de ce schéma. Le produit Ciproxin HC est otique et ne s’utilise pas ici [S8, S21].</p><p>La FI interdit grossesse/allaitement hors cas particulier ; l’OFSP permet toutes les molécules citées pendant allaitement et choisit ceftriaxone en grossesse. Cette divergence reste explicite pour le prescripteur. Tizanidine/agomélatine contre-indiquées, risques tendineux majorés par corticoïdes, cations diminuant absorption ; ne pas interrompre un remplacement vital pour régler le choix d’une prophylaxie [S5, S8, S21].</p>''')
pop('codes','Classification et manifestation','''<p>E35.0* thyroïde, E35.1* surrénale, E35.8* autres glandes. Astérisque jamais seul ; code étiologique primaire et manifestation sont distingués. Exemples nommés : A18.8†thyroïde tuberculeuse, A18.7†Addison tuberculeux, A39.1†Waterhouse-Friderichsen méningococcique. Pas attribution automatique aux autres étiologies [S1–S3].</p>''')
pop('cortisol','Cortisol : contexte du test','''<p>Repères NICE2024 pour bilan matinal8–9h, âge≥1an, immunodosages modernes :<150nmol/Lsuspect,150–300incertain,>300déficit très improbable. Autres méthodes/références et nourrisson nécessitent autre lecture. Ce n’est pas un seuil de non-traitement en choc ; exposition hormonale et protéines porteuses modifient le résultat [S4, S5, S10].</p>''')
pop('contacts','Contact étroit : définition et délai','''<p>OFSP20janvier2025 : contacts étroits de sept jours avant signes à24heures après traitement spécifique ; foyer et contact intense avec sécrétions, situations de petite enfance selon critères. Simple proximité ou même classe scolaire n’est pas toujours une indication. Prophylaxie idéalement24heures et début au plus dix jours après exposition ; personne symptomatique évaluée comme possible cas, pas seulement prophylaxie [S8].</p>''')
pop('profiles','Objectifs suisses de formation','''<p>PROFILES2017 : décompensation, choc/hypotension sévère, méningisme, altération de conscience et douleur abdominale ; SSP88purpura et214pressions extrêmes complètent le raisonnement. Rapprochement pédagogique, pas correspondance officielle E35 ni question d’examen garantie [S24].</p>''')
pop('semio','Sémiologie et niveau de soins','''<p>L’examen recherche d’abord la gravité : circulation, conscience, glucose, respiration, purpura et absorption des médicaments. Ni pigmentation absente ni potassium normal ne suffisent à exclure une atteinte aiguë. Les neuf sections de sémiologie scientifique lient mécanisme, examen, interprétation, différentiels, urgence et limites [S4–S8, S10].</p>''')
pop('routes','Voies parentérales et produit exact','<p>IM signifie intramusculaire ; IV intraveineux. Ces voies ne rendent pas les doses ou préparations équivalentes. Pour la crise, hydrocortisone parentérale selon population et formulation ; pour Rocephin intramusculaire, le solvant peut contenir lidocaïne et cette solution ne doit jamais être injectée dans une veine. Le produit exact, sa voie et ses contre-indications sont vérifiés [S16, S19].</p>')
pop('waterhouse','Syndrome septique et hémorragie surrénalienne','<p>Waterhouse-Friderichsen désigne un tableau septique fulminant avec hémorragie surrénalienne bilatérale, classiquement méningococcique mais décrit avec d’autres agents. Les soins infectieux, circulatoires et endocriniens nécessaires se font en parallèle. Seul le contexte méningococcique justifie l’exemple A39.1†/E35.1* ; une série de décès à autopsie ne donne pas une létalité de tous les patients [S2, S8, S15].</p>')
