source_by_id={s['id']:s for s in ledger}
def cite(m):
 ids=[]
 for part in m[1].split(','):
  nums=re.findall(r'S?(\d+)',part)
  if ('–' in part or '—' in part) and len(nums)==2:ids.extend('S'+str(i) for i in range(int(nums[0]),int(nums[1])+1))
  else:ids.extend('S'+n for n in nums)
 ids=list(dict.fromkeys(i for i in ids if i in source_by_id))
 return '['+', '.join(f'<a data-reference-source="1" href="{html.escape(source_by_id[i]["url"],quote=True)}" target="_blank" rel="noopener">{i}</a>' for i in ids)+']' if ids else m[0]
terms={'Solu-Cortef':'hydrocortisone','Solu-CORTEF':'hydrocortisone','Hydrocortisone Galepharm':'galepharm','Florinef':'fludrocortisone','Rocephin':'ceftriaxone','Rimactan':'rifampicine','Ciproxine':'ciprofloxacine','PROFILES':'profiles','IM':'routes','IV':'routes','Waterhouse-Friderichsen':'waterhouse'}
source_terms={'E35.0':'S2','E35.1':'S2','E35.8':'S2','A18.8':'S2','A18.7':'S2','A39.1':'S2','NICE':'S5','ESE':'S6','BSPED':'S7','OFSP':'S8','SSI':'S22','HC':'S21','Act-O-Vial':'S16','V1.2024':'S9','SSP':'S24'}
pat=re.compile(r'(?<![\w])('+'|'.join(re.escape(k) for k in sorted(set(terms)|set(source_terms),key=len,reverse=True))+r')(?![\w])')
for p in (R/'chapters/E35').glob('*.html'):
 parts=[];protected=0;inlocal=False;instyle=False
 for x in re.split(r'(<[^>]+>)',p.read_text()):
  if x.startswith('<'):
   if x.startswith('<style'):instyle=True
   elif x.startswith('</style'):instyle=False
   if re.match(r'<template\s+data-pop=',x):inlocal=True
   if x.startswith('</template'):inlocal=False
   if re.match(r'<(?:a|button|style)(?:\s|>)',x):protected+=1
   elif re.match(r'</(?:a|button|style)',x):protected=max(0,protected-1)
   parts.append(x);continue
  if instyle:parts.append(x);continue
  # Prose-only spacing, including quiz option text; never rewrite attributes or CSS.
  x=re.sub(r'(?<=[a-zéèêûùîïàç])(?=\d)',' ',x);x=re.sub(r'(?<=\d)(?=[A-Za-zÀ-ÿ])',' ',x);x=re.sub(r'\b(NICE|ESE|BSPED|OFSP|SSI|PROFILES|FI|IV|IM|SSP)(?=\d)',r'\1 ',x);x=re.sub(r'([:;])(?=\d)',r'\1 ',x)
  x=re.sub(r'(?<=%)(?=[A-Za-zÀ-ÿ])',' ',x);x=re.sub(r'(kg|/j)(?=max|chez)',r'\1 ',x);x=re.sub(r'ans(?=comme|et>)','ans ',x);x=re.sub(r'(?<=[A-Za-zÀ-ÿ]),(?=\d)',', ',x)
  if protected:parts.append(x);continue
  def linkterm(m):
   word=m[1]
   if word in source_terms:sid=source_terms[word]
   elif inlocal:sid={'hydrocortisone':'S16','galepharm':'S17','fludrocortisone':'S18','ceftriaxone':'S19','rifampicine':'S20','ciprofloxacine':'S21','profiles':'S24','routes':'S16','waterhouse':'S15'}[terms[word]]
   else:return w(terms[word],word)
   return '<a data-reference-source="1" href="'+source_by_id[sid]['url']+'" target="_blank" rel="noopener">'+word+'</a>'
  x=pat.sub(linkterm,x);x=re.sub(r'\[((?:S\d+)[^\[\]]*)\]',cite,x);parts.append(x)
 t=''.join(parts);t=re.sub(r'(</(?:p|section|table|template|figure|nav)>)(?=<)',r'\1\n',t);p.write_text(t)
# Remove unused local definitions; every remaining template has a real control.
allsource=''.join(p.read_text() for p in (R/'chapters/E35').glob('*.html'));used=set(re.findall(r'data-k="([^"]+)"',allsource));pp=R/'chapters/E35/E35_pop1.html';body=pp.read_text();body=re.sub(r'<template data-pop="([^"]+)".*?</template>',lambda m:m[0] if m[1] in used else '',body,flags=re.S);pp.write_text(body)
print('14 clinical sections,4 exams,6 pharmacology,6 sciences/9 semiology; local definitions',len(re.findall(r'data-pop=',body)),'summaries',len(summaries))
